/**
 * The checks behind `pnpm docs:check` (docs/ENGINE_WORKFLOW.md section 8). Pure: it reads files under `root` and returns problems, so a test can run it on a
 * temporary folder. It fails when
 *   1. a path in the first column of the section 1 table of docs/ENGINE_WORKFLOW.md is missing (rows marked planned, local or generated by the owner's
 *      table are skipped: a local folder such as ledger/ does not exist on a fresh checkout);
 *   2. an ADR file has no Status line;
 *   3. a frozen prompt's sha256 differs from prompts/VERSIONS.md, or a prompt file is not listed there.
 * A hash is taken after converting line endings to LF (what git stores), so a Windows checkout and a Linux one agree.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";

export const sha256Lf = (text: Buffer | string): string => createHash("sha256").update(String(text instanceof Buffer ? text.toString("latin1") : text).replace(/\r\n/g, "\n"), "latin1").digest("hex");

const read = (root: string, rel: string): string => readFileSync(join(root, rel), "utf8");

/** The rows of the table under "## 1." of the workflow file: [paths in the first column, state]. */
export function docSetRows(workflow: string): Array<{ paths: string[]; state: string }> {
  const start = workflow.indexOf("## 1.");
  const end = workflow.indexOf("\n## 2.");
  const section = workflow.slice(start, end === -1 ? undefined : end);
  const rows: Array<{ paths: string[]; state: string }> = [];
  for (const line of section.split(/\r?\n/)) {
    if (!line.startsWith("|") || /^\|\s*-/.test(line) || /^\|\s*Path\s*\|/.test(line)) continue;
    const cells = line.split("|").slice(1, -1).map((c) => c.trim());
    if (cells.length < 3) continue;
    rows.push({ paths: [...cells[0]!.matchAll(/`([^`]+)`/g)].map((m) => m[1]!), state: cells[2]! });
  }
  return rows;
}

export function checkDocs(root: string): string[] {
  const problems: string[] = [];

  // 1. the doc set
  const workflowPath = "docs/ENGINE_WORKFLOW.md";
  if (!existsSync(join(root, workflowPath))) return [`${workflowPath} is missing`];
  for (const row of docSetRows(read(root, workflowPath))) {
    if (/\b(planned|local|generated)\b/i.test(row.state) && !/\bcurrent\b/i.test(row.state)) continue;
    for (const p of row.paths) {
      // a pattern such as docs/adr/NNNN-title.md stands for a folder of files
      const target = /NNNN/.test(p) ? dirname(p) : p;
      if (!existsSync(join(root, target))) problems.push(`the doc set lists ${p}, which is missing`);
    }
  }

  // 2. every ADR has a Status line
  const adrDir = join(root, "docs", "adr");
  if (existsSync(adrDir)) {
    for (const f of readdirSync(adrDir).filter((n) => n.endsWith(".md")).sort()) {
      if (!/^Status:/m.test(readFileSync(join(adrDir, f), "utf8"))) problems.push(`docs/adr/${f} has no Status line`);
    }
  }

  // 3. prompts: every file is listed, and a frozen file matches its recorded hash
  const versionsPath = "prompts/VERSIONS.md";
  if (!existsSync(join(root, versionsPath))) {
    problems.push(`${versionsPath} is missing`);
  } else {
    const listed = new Map<string, { sha?: string; frozen: boolean }>();
    for (const line of read(root, versionsPath).split(/\r?\n/)) {
      if (!line.startsWith("|")) continue;
      const cells = line.split("|").slice(1, -1).map((c) => c.trim());
      const name = cells[0]?.match(/^`([^`]+\.md)`$/)?.[1];
      if (!name) continue;
      listed.set(name, { sha: cells[1]?.match(/`?([0-9a-f]{64})`?/)?.[1], frozen: /\bfrozen\b/i.test(cells[2] ?? "") });
    }
    const promptDir = join(root, "prompts");
    for (const f of readdirSync(promptDir).filter((n) => n.endsWith(".md") && n !== "VERSIONS.md").sort()) {
      const entry = listed.get(f);
      if (!entry) {
        problems.push(`prompts/${f} is not listed in ${versionsPath}`);
        continue;
      }
      if (entry.frozen) {
        const actual = sha256Lf(readFileSync(join(promptDir, f)));
        if (!entry.sha) problems.push(`prompts/${f} is frozen but ${versionsPath} records no sha256 for it`);
        else if (entry.sha !== actual) problems.push(`prompts/${f} is frozen and its sha256 is ${actual}, but ${versionsPath} records ${entry.sha}`);
      }
    }
  }
  return problems;
}
